/* ============ LOGIN SCREEN ============ */
function renderLogin(){
  el('root').innerHTML=`<div class="center"><div class="authcard">
    <div class="authlogo logo-mark"><img class="logomark" src="${MLOGO}" alt="Mercury"></div>
    <h1>Mercury</h1>
    <p class="sub">Operations Platform — sign in to continue</p>
    <form id="loginForm">
      <div class="field"><label>Email</label><input type="email" id="email" required autocomplete="username" placeholder="you@mercuryas.co.uk"></div>
      <div class="field"><label>Password</label><input type="password" id="pw" required autocomplete="current-password" placeholder="••••••••"></div>
      <button class="btn" id="loginBtn" type="submit">Sign in</button>
      <div class="authmsg" id="authMsg"></div>
    </form>
    <div class="authfoot">Mercury Automated Solutions · secure client &amp; field operations</div></div></div>`;
  el('loginForm').addEventListener('submit', async e=>{
    e.preventDefault();
    const btn=el('loginBtn'), msg=el('authMsg');
    btn.disabled=true; btn.textContent='Signing in…'; msg.textContent=''; msg.className='authmsg';
    const {error} = await sb.auth.signInWithPassword({email:el('email').value.trim(), password:el('pw').value});
    if(error){ msg.textContent=error.message; msg.className='authmsg err'; btn.disabled=false; btn.textContent='Sign in'; return; }
    const {data:{session}} = await sb.auth.getSession();
    SESSION=session; await startApp();
  });
}

/* ============ LOAD PROFILE + CLIENTS, THEN RENDER SHELL ============ */
async function startApp(){
  el('root').innerHTML=`<div class="center"><div class="muted">Loading your dashboard…</div></div>`;
  // profile
  const {data:prof} = await sb.from('profiles').select('*').eq('id',SESSION.user.id).maybeSingle();
  PROFILE = prof || {role:'client', full_name:SESSION.user.email, email:SESSION.user.email};
  // clients (RLS lets everyone read the list; we restrict non-admins to their own)
  let {data:clients} = await sb.from('clients').select('*').order('name');
  clients = clients || [];
  if(PROFILE.role!=='admin' && PROFILE.client_id) clients = clients.filter(c=>c.id===PROFILE.client_id);
  CLIENTS = clients;
  CLIENT = CLIENTS[0] || null;
  // clients see the portal view; admins/engineers default to internal
  VIEW = (PROFILE.role==='client') ? 'client' : 'internal';
  document.body.classList.toggle('client', VIEW==='client');
  // Admins land on the business-wide HQ overview; clients/engineers go into their dashboard.
  if(PROFILE.role==='admin'){
    await loadHQ();
    await loadLogins();
    await loadSuppliers();
    await loadEngHr();
    await loadEngReg();
    renderShell();
    go('hq');
  } else if(PROFILE.role==='supplier'){
    // Labour supplier: self-service portal, only their own data
    await loadSupplierData();
    renderShell();
    go('sup_home');
  } else if(CLIENT){
    renderShell();
    await loadClientData(); go('overview');
  } else {
    renderShell();
    go('overview'); // graceful: shows a "no client" message instead of a blank screen
  }
  /* If the visitor arrived from a notification email (?page=callouts), open that page. */
  try{ const want=new URLSearchParams(location.search).get('page'); if(want && TITLES[want]) go(want); }catch(e){}
}

/* Enter a specific client's dashboard (from the Clients hub or dropdown) */
async function enterClient(id){ return enterClientTo(id,'overview'); }
async function enterClientTo(id,page,focusId){
  CLIENT = CLIENTS.find(c=>c.id===id) || CLIENT;
  if(!CLIENT) return;
  await loadClientData();
  const crumb=document.querySelector('.crumb'); if(crumb) crumb.textContent=CLIENT.name;
  const sel=el('cliSelect'); if(sel) sel.value=CLIENT.id;
  go(page||'overview');
  if(focusId){ setTimeout(()=>{ const elx=document.getElementById('rec_'+focusId); if(elx){ elx.scrollIntoView({behavior:'smooth',block:'center'}); elx.classList.add('flash'); } }, 250); }
}
/* Notify a client (created by Mercury staff). Best-effort; never blocks UI. */
async function notifyClient(clientId, kind, title, linkPage, body){
  if(!clientId || !title) return;
  if(PROFILE && PROFILE.role==='client') return;   // clients don't notify themselves
  try{ await sb.from('notifications').insert({client_id:clientId, kind:kind||null, title:title, body:body||null, link_page:linkPage||null}); }
  catch(e){ console.warn('notify failed (continuing):', e&&e.message||e); }
}
/* ---- client notification bell (client portal only) ---- */
function notifBell(){
  if(!PROFILE || PROFILE.role!=='client') return '';
  const ns=(DATA.notifications||[]).slice().sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));
  const unread=ns.filter(n=>!n.read_at);
  const ic=k=>({quote:'📝',request:'🛠',job:'🗓',document:'📁',report:'📋'}[k]||'🔔');
  const items=ns.slice(0,30).map(n=>`<div class="notif-item ${n.read_at?'read':'unread'}" onclick="openNotif('${n.id}','${esc(n.link_page||'overview')}')"><div class="ni-ic">${ic(n.kind)}</div><div class="ni-bd"><div class="ni-t">${esc(n.title)}</div>${n.body?`<div class="ni-m">${esc(n.body)}</div>`:''}<div class="ni-w">${esc(rel(n.created_at))}</div></div>${n.read_at?'':'<span class="ni-dot"></span>'}</div>`).join('');
  return `<button class="notif-btn" onclick="toggleNotifPanel(event)" title="Notifications">🔔${unread.length?`<span class="notif-badge">${unread.length>9?'9+':unread.length}</span>`:''}</button>
    <div class="notif-panel" id="notifPanel"><div class="notif-head">Notifications${unread.length?` · ${unread.length} new`:''}${unread.length?`<button class="notif-clear" onclick="markAllNotifsRead(event)">Mark all read</button>`:''}</div>${items||'<div class="notif-empty">You are all caught up 🎉</div>'}</div>`;
}
function refreshNotifBell(){ const w=el('notifWrap'); if(w) w.innerHTML=notifBell(); }
function toggleNotifPanel(e){ if(e){e.stopPropagation();} const w=el('notifWrap'); if(w) w.classList.toggle('open'); }
async function openNotif(id,page){
  const w=el('notifWrap'); if(w) w.classList.remove('open');
  const n=(DATA.notifications||[]).find(x=>x.id===id);
  if(n && !n.read_at){ n.read_at=new Date().toISOString(); refreshNotifBell(); try{ await sb.from('notifications').update({read_at:n.read_at}).eq('id',id); }catch(e){} }
  if(page) go(page);
}
function markAllNotifsRead(e){ if(e){e.stopPropagation();} const now=new Date().toISOString(); const un=(DATA.notifications||[]).filter(n=>!n.read_at); if(!un.length) return; un.forEach(n=>n.read_at=now); refreshNotifBell(); try{ sb.from('notifications').update({read_at:now}).is('read_at',null).eq('client_id',CLIENT.id); }catch(e){} }

/* ---- supplier notification bell (supplier portal + admin preview) ---- */
let SUPNOTIFS=[];
async function loadSupNotifs(supplierId){ try{ let q=sb.from('supplier_notifications').select('*'); if(supplierId) q=q.eq('supplier_id',supplierId); const r=await q; SUPNOTIFS=r.data||[]; }catch(e){ SUPNOTIFS=[]; } }
async function notifySupplier(supplierId, kind, title, linkPage, body){
  if(!supplierId || !title) return;
  try{ await sb.from('supplier_notifications').insert({supplier_id:supplierId, kind:kind||null, title:title, body:body||null, link_page:linkPage||null}); }
  catch(e){ console.warn('supplier notify failed (continuing):', e&&e.message||e); }
}
function supBellActive(){ return PROFILE && (PROFILE.role==='supplier' || !!SUPPREVIEW); }
function supNotifBell(){
  if(!supBellActive()) return '';
  const ns=(SUPNOTIFS||[]).slice().sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));
  const unread=ns.filter(n=>!n.read_at);
  const ic=k=>({assignment:'🗓',timesheet:'⏱',feedback:'⭐',info:'🔔'}[k]||'🔔');
  const items=ns.slice(0,30).map(n=>`<div class="notif-item ${n.read_at?'read':'unread'}" onclick="openSupNotif('${n.id}','${esc(n.link_page||'sup_home')}')"><div class="ni-ic">${ic(n.kind)}</div><div class="ni-bd"><div class="ni-t">${esc(n.title)}</div>${n.body?`<div class="ni-m">${esc(n.body)}</div>`:''}<div class="ni-w">${esc(rel(n.created_at))}</div></div>${n.read_at?'':'<span class="ni-dot"></span>'}</div>`).join('');
  return `<button class="notif-btn" onclick="toggleNotifPanel(event)" title="Notifications">🔔${unread.length?`<span class="notif-badge">${unread.length>9?'9+':unread.length}</span>`:''}</button>
    <div class="notif-panel" id="notifPanel"><div class="notif-head">Notifications${unread.length?` · ${unread.length} new`:''}${unread.length?`<button class="notif-clear" onclick="markAllSupNotifsRead(event)">Mark all read</button>`:''}</div>${items||'<div class="notif-empty">You are all caught up 🎉</div>'}</div>`;
}
function refreshSupBell(){ const w=el('notifWrap'); if(w) w.innerHTML=supNotifBell(); }
async function openSupNotif(id,page){
  const w=el('notifWrap'); if(w) w.classList.remove('open');
  const n=(SUPNOTIFS||[]).find(x=>x.id===id);
  if(n && !n.read_at){ n.read_at=new Date().toISOString(); refreshSupBell(); try{ await sb.from('supplier_notifications').update({read_at:n.read_at}).eq('id',id); }catch(e){} }
  if(page) go(page);
}
function markAllSupNotifsRead(e){ if(e){e.stopPropagation();} const now=new Date().toISOString(); const un=(SUPNOTIFS||[]).filter(n=>!n.read_at); if(!un.length) return; un.forEach(n=>n.read_at=now); refreshSupBell(); try{ if(SUPPLIER) sb.from('supplier_notifications').update({read_at:now}).is('read_at',null).eq('supplier_id',SUPPLIER.id); }catch(e){} }
/* which bell to show in the top bar */
function bellHtml(){ return supBellActive()?supNotifBell():notifBell(); }

